INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 12, 'theory', 'Quiz: boot, systemd and packages');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 0, 'Why does the kernel need the initramfs initial image?', '["It holds modules and scripts to find the disk, unlock encryption, assemble volumes and mount the real root", "It stores user data", "It replaces the bootloader", "It is a backup copy of the kernel"]', 0, 'The disk driver or encryption is often built as a module, and it can only be loaded from here.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 1, 'How does Requires differ from After in a unit file?', '["They don''t: they are interchangeable", "After starts the unit itself", "Requires is a dependency (can''t work without the unit), After is only the start order", "Requires sets only the order"]', 2, 'Order and dependency are set separately. systemd starts independent units in parallel.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 2, 'What is socket activation?', '["The service is started on every packet and exits at once", "systemd listens on the port itself and starts the service on the first connection, handing over the ready socket", "Sockets are opened only by hand", "The service closes sockets after it starts"]', 1, 'While nobody connects, there is no service. The kernel queues connections in the socket queue, so the start order doesn''t matter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 3, 'What is the StartLimit limit for?', '["To limit the number of simultaneous clients", "To limit the journal size", "To limit the time of a single start", "To stop an endless restart loop: after a series of quick crashes the unit is marked as failed"]', 3, 'The status shows the cause of the last crash and the last lines of the journal.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 4, 'How do you view the errors of the nginx service over the last hour?', '["systemctl log nginx --errors", "cat /var/log/nginx | grep hour", "journalctl -u nginx -p err --since \"1 hour ago\"", "dmesg -u nginx -p err"]', 2, 'The journal is structured: you can filter by unit, severity level and time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 5, 'What does Requires= mean in a systemd unit?', '["A dependency: this unit won''t start without the required one; the start order is set separately with the After= directive", "The unit starts strictly after all the others", "The unit restarts on any error", "The unit reads its settings from the given file"]', 0, 'Dependency and order are different things. Requires says "needed", After says "after".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 6, 'What is socket activation?', '["The service itself opens a socket at boot", "The network card starts the service in hardware", "All services are started one by one through a socket", "systemd itself opens the port and starts the service on the first connection, handing it the ready socket"]', 3, 'Clients can connect while the service is not ready yet: connections wait in the queue of the open socket.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 12, 7, 'Why is initramfs needed at boot?', '["It stores user data while the system runs", "A small in-memory filesystem with drivers that lets the kernel find and mount the real root", "It replaces the bootloader", "It contains the network settings of all services"]', 1, 'The disk or encryption driver may be a module, and it lives on the disk itself. Initramfs breaks this circle.');
